/**
 * Statements for the step hook's differential test: every stage, every kind of `match` step, nested blocks,
 * functions, `fetch` and its sub-queries, writes of each kind, and refusals. Run in order, against one store.
 */
export type CorpusStatement = readonly ['define' | 'write' | 'read', string];

export const PEOPLE_CORPUS: readonly CorpusStatement[] = [
  [
    'define',
    [
      'define',
      'attribute name, value string;',
      'attribute age, value integer;',
      'attribute nick, value string;',
      'entity person, owns name, owns age, owns nick, plays employment:employee, plays friendship:friend;',
      'entity company, owns name, plays employment:employer;',
      'relation employment, relates employee, relates employer;',
      'relation friendship, relates friend;',
      'fun adult_ages() -> { integer }: match $p isa person, has age $a; $a >= 18; return { $a };',
    ].join('\n'),
  ],
  ['write', 'insert $a isa person, has name "Ann", has age 30; $b isa person, has name "Bob", has age 17; $c isa person, has name "Cid", has age 45, has nick "C";'],
  ['write', 'insert $x isa company, has name "Acme";'],
  ['write', 'match $p isa person, has name "Ann"; $c isa company; insert (employee: $p, employer: $c) isa employment;'],
  ['write', 'match $p isa person, has name "Bob"; $q isa person, has name "Cid"; insert (friend: $p, friend: $q) isa friendship;'],
  ['read', 'match $p isa person, has name $n; select $n;'],
  ['read', 'match $p isa person, has age $a; $a > 20; select $p;'],
  ['read', 'match $p isa person, has name $n; not { (employee: $p) isa employment; }; select $n;'],
  ['read', 'match { $x isa person; } or { $x isa company; }; $x has name $n; select $n;'],
  ['read', 'match $p isa person, has name $n; try { $p has nick $k; }; select $n, $k;'],
  ['read', 'match $p isa person, has age $a; let $d = $a * 2; $d > 50; select $d;'],
  ['read', 'match $p isa person; $q isa person; $p is $q; select $p;'],
  ['read', 'match $p isa person, has name $n; sort $n desc; limit 2; select $n;'],
  ['read', 'match $p isa person, has name $n; sort $n; offset 1; distinct; select $n;'],
  ['read', 'match $p isa person, has age $a; reduce $s = sum($a);'],
  ['read', 'match (employee: $p, employer: $c) isa employment; $p has name $n; select $n;'],
  ['read', 'match $r isa friendship (friend: $p); $p has name $n; select $n;'],
  ['read', 'match $p isa person, has name $n; fetch { "name": $n, "ages": [ $p.age ] };'],
  ['read', 'match $p isa person, has name $n; fetch { "n": $n, "others": [ match $p has name $o; $o != $n; fetch { "o": $o }; ] };'],
  ['read', 'with fun names($x: person) -> { name }: match $x has name $n; return { $n }; match $p isa person; let $m in names($p); select $m;'],
  ['read', 'match let $g in adult_ages(); $g > 40; select $g;'],
  ['read', 'match $p isa person, has name "Nobody"; select $p;'],
  ['read', 'match $p isa person, has name $n; match $p has age $a; $a < 40; select $n, $a;'],
  ['read', 'match $p isa person, has name $n; { $n == "Ann"; } or { $n == "Bob"; }; select $n;'],
  ['read', 'match $x isa $t; $t label person; select $x;'],
  ['read', 'match $n isa name "Ann"; select $n;'],
  ['read', 'match $p isa unknown-type; select $p;'],
  ['read', 'match $p isa person, has age $a; $a > "x"; select $a;'],
  ['write', 'insert $p isa person, has age "not a number";'],
  ['write', 'match $p isa person, has name "Bob"; insert $p has nick "B";'],
  ['write', 'match $p isa person, has nick $k; delete has $k of $p;'],
  ['write', 'match $p isa person, has name "Ann"; update $p has age 31;'],
  ['write', 'put $p isa person, has name "Dee";'],
  ['write', 'put $p isa person, has name "Dee";'],
  ['write', 'match $p isa person, has name "Nobody"; insert $p has nick "N";'],
  ['write', 'match $p isa person, has name "Cid"; $f isa friendship (friend: $p); delete $f;'],
  ['write', 'match $p isa person, has name "Ann"; delete $p;'],
  ['read', 'match $p isa person, has name $n; try { $p has age $a; }; select $n, $a;'],
];
